const e = $('Bei Aufruf').first().json;
const v = $input.first().json.vorgang;
if (!e.mail || !e.mail.message_id) throw fehlerklassen.epaFehler('UNGUELTIGES_FORMAT', v.vorgangs_id, 'mail.message_id fehlt');
