function gleich(a, b) {
	if (typeof a === 'number' || typeof b === 'number') return Number(a) === Number(b);
	return String(a).replace(/\s+/g, ' ').trim().toLowerCase() === String(b).replace(/\s+/g, ' ').trim().toLowerCase();
