	return bloecke.map((bl) => {
		const zeilen = bl.felder.map((f) => `${esc(bl.gruppe ? (f.kurzname || f.anzeigename) : f.anzeigename)}: ${esc(wertText(f, (daten || {})[f.feldname]))}`);
